import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { resolve, dirname } from 'node:path';

const destination = 'experiments/phase1/cli/results/612-documentation-and-git.json';
const sha = (path: string) => new Bun.CryptoHasher('sha256').update(readFileSync(path)).digest('hex');
function git(...args: string[]) {
    const result = Bun.spawnSync(['git', '--no-optional-locks', ...args], { stdout: 'pipe', stderr: 'pipe', env: { ...process.env, GIT_OPTIONAL_LOCKS: '0' } });
    if (result.exitCode) throw Error(result.stderr.toString());
    return result.stdout.toString().trimEnd();
}
const original = JSON.parse(readFileSync('target/increment612-entry.json', 'utf8'));
const documents = ['README.md', 'ARCHITECTURE.md', 'ROADMAP.md', 'PROGRESS.md', 'docs/OPEN_QUESTIONS.md', 'docs/phase1/README.md', 'docs/phase1/INCREMENT_6_1_LOCAL_CLI_FOUNDATION.md', 'docs/phase1/INCREMENT_6_1_2_STORAGE_SEMANTICS_DOCUMENTATION.md'];
const failures: string[] = [];
let links = 0;
const outsideFences = (text: string) => text.replace(/^```[^\n]*\n[\s\S]*?^```\s*$/gm, '');
const slug = (text: string) => text.trim().toLowerCase().replace(/[`*_~]/g, '').replace(/[^\p{L}\p{N}\s_-]/gu, '').replace(/\s/g, '-');
for (const path of documents) {
    const source = readFileSync(path, 'utf8');
    if ((source.match(/^```/gm)?.length ?? 0) % 2) failures.push(`Unclosed code fence: ${path}`);
    for (const match of outsideFences(source).matchAll(/\[[^\]\n]+\]\(([^)\n]+)\)/g)) {
        const href = match[1];
        if (/^[a-z][a-z0-9+.-]*:/i.test(href)) continue;
        links++;
        const [file, fragment] = href.split('#');
        const target = file ? resolve(dirname(path), decodeURIComponent(file)) : resolve(path);
        if (!existsSync(target)) { failures.push(`Missing local link: ${path} -> ${href}`); continue; }
        if (fragment && target.endsWith('.md')) {
            const anchors = [...outsideFences(readFileSync(target, 'utf8')).matchAll(/^#{1,6}\s+(.+)$/gm)].map(m => slug(m[1]));
            if (!anchors.includes(decodeURIComponent(fragment))) failures.push(`Missing local heading: ${path} -> ${href}`);
        }
    }
}
const expectedReadonlyTokens = ['domain-state read-only', 'SQLITE_OPEN_READ_WRITE', 'BEGIN IMMEDIATE', 'wal_checkpoint(TRUNCATE)', '.local-context.lock', '-shm', 'timestamps', 'storage_or_service_failure'];
for (const path of ['README.md', documents.at(-1)!]) {
    const text = readFileSync(path, 'utf8');
    for (const token of expectedReadonlyTokens) if (!text.includes(token)) failures.push(`Missing storage disclosure ${token}: ${path}`);
}
for (const path of ['ARCHITECTURE.md','ROADMAP.md','docs/OPEN_QUESTIONS.md','PROGRESS.md',documents.at(-1)!]) {
    const text = readFileSync(path, 'utf8');
    for (const token of ['F-611-02','atomic staging','explicit operator recovery','Phase 2 production readiness']) {
        if (!text.includes(token)) failures.push(`Missing recovery gate ${token}: ${path}`);
    }
}
const adr = [...new Bun.Glob('docs/adr/000*.md').scanSync('.')].map(path => path.replaceAll('\\', '/')).sort().map(path => ({ path, status: readFileSync(path, 'utf8').match(/^- Status: (.+)$/m)?.[1], sha256: sha(path) }));
if (adr.length !== 7 || adr.some(a => a.sha256 !== original.files[a.path])) failures.push('ADR inventory/status/content changed');
const definedRequirements = new Set([...readFileSync('REQUIREMENTS.md','utf8').matchAll(/^\| ([FSQ]-\d{2}) \|/gm)].map(m => m[1]));
for (const id of [...readFileSync(documents.at(-1)!, 'utf8').matchAll(/\b[FSQ]-\d{2}\b/g)].map(m => m[0])) if (!definedRequirements.has(id)) failures.push(`Undefined requirement: ${id}`);
const final = {
    head: git('rev-parse', 'HEAD'), branch: git('branch', '--show-current'), upstream: git('rev-parse', '--abbrev-ref', '@{upstream}'), ahead_behind: git('rev-list', '--left-right', '--count', 'HEAD...@{upstream}'),
    status: git('status', '--porcelain=v1', '--untracked-files=all'), refs: git('for-each-ref', '--format=%(refname) %(objectname) %(symref)'), history: git('log', '--all', '--format=%H %P %aI %s'), index: git('ls-files', '--stage'), index_sha256: sha('.git/index')
};
const comparison = Object.fromEntries(['head','branch','upstream','ahead_behind','refs','history','index','index_sha256'].map(key => [key, original[key] === final[key as keyof typeof final]]));
for (const [key, passed] of Object.entries(comparison)) if (!passed) failures.push(`Git state changed: ${key}`);
const changed = Object.keys(original.files).filter(path => sha(path) !== original.files[path]);
const unexpected = changed.filter(path => !documents.includes(path));
if (unexpected.length) failures.push(`Unexpected existing file changes: ${unexpected.join(', ')}`);
const preservedReview = sha('docs/phase1/INCREMENT_6_1_1_INDEPENDENT_REVIEW.md') === original.files['docs/phase1/INCREMENT_6_1_1_INDEPENDENT_REVIEW.md'];
if (!preservedReview) failures.push('Historical independent review changed');
const lines = final.status.split('\n').filter(Boolean);
const counts = { staged: lines.filter(l => ![' ', '?'].includes(l[0])).length, modified: lines.filter(l => l[0] !== '?' && l[1] !== ' ').length, untracked: lines.filter(l => l.startsWith('??')).length };
if (counts.staged) failures.push('Index has staged changes');
const validation = JSON.parse(readFileSync('experiments/phase1/cli/results/612-1794006630618.json','utf8'));
const drift = Object.entries(validation.non_markdown_input_sha256).filter(([path, hash]) => sha(path) !== hash).map(([path]) => path);
if (drift.length) failures.push(`Validation source drift: ${drift.join(', ')}`);
const report = { increment: '6.1.2', observed_at_utc: new Date().toISOString(), status: failures.length ? 'Failed' : 'Passed', failures,
    documentation: { paths_sha256: Object.fromEntries(documents.map(path => [path, sha(path)])), local_links_checked: links, adrs: adr, preserved_independent_review: preservedReview, checks: ['Local file links and heading fragments','Fence pairing','Storage-layer terminology disclosures','Mandatory open recovery gate','Existing requirement IDs','ADR statuses/content unchanged'], limits: ['Narrow Markdown syntax checks; no full renderer or live external-link checks.'] },
    git: { initial: original, final, comparison, counts, intended_existing_document_changes: changed, unexpected_existing_changes: unexpected, all_non_documentation_and_unrelated_files_preserved: unexpected.length === 0 },
    validation_non_markdown_inputs_match_final: drift.length === 0, validation_drift: drift, checker_source: readFileSync('target/increment612-assurance.ts','utf8') };
writeFileSync(destination, JSON.stringify(report,null,2) + '\n');
console.log(JSON.stringify({status: report.status, documents: documents.length, links, preserved_review: preservedReview, adr_count: adr.length, counts, comparison, unexpected, failures}));
if (failures.length) process.exit(1);
